UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"月別ページ ?event_year=YYYY&event_month=M（WordPress・Tailwind）。カードは独自タグ <d id=\"post-N\">。クラスは Tailwind のユーティリティなので、日付と時刻はカード全体の text に正規表現を当てる（2026. 11.01 / OPEN/START： 19:00/19:30。ラベルが二重の「OPEN/START： OPEN/START:19:00/19:30」もある）。「Coming soon…」の仮カードは skip。一覧に出演者・完売表記はない。","url_template":"https://spaceodd.jp/schedule/?event_year={YYYY}&event_month={M}","item":"d.fadeInUp","skip":[{"reason":"placeholder: coming soon","when":{"in":"h2","text_matches":"^Coming soon"}}],"fields":{"date":{"source":{},"pattern":"(?<year>\\d{4})\\.?\\s*(?<month>\\d{1,2})\\.(?<day>\\d{1,2})"},"title":{"sources":[{"selector":"h2"}],"mode":"first"},"times":{"source":{},"patterns":["OPEN/START[：:][^0-9]*(?<open>\\d{1,2}:\\d{2})\\s*/\\s*(?<start>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-daikanyama-spaceodd';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"月別ページ（WordPress）。日付は 11/01 形式で、年はページ見出し（2026.11）から取る。一覧に start 時刻はなく open のみ（start は詳細ページにあるかもしれないが未確認）。タイトルは補助行 title-top / title / title-bottom を連結。【公演中止】はタイトルに入るので cancelled に写す。カテゴリ（RECOMMEND/FEATURE）は status ではないので使わない。JSON-LD の Event は時刻も出演者名も持たないので使わない。","url_template":"https://www.unit-tokyo.com/schedule/{YYYY}-{MM}/","item":".p-schedule__body > .p-schedule__item","fields":{"date":{"source":{"selector":".p-schedule__item-date"},"pattern":"(?<month>\\d{1,2})/(?<day>\\d{1,2})","year_source":{"source":{"from":"page","selector":".p-schedule__header-title"},"pattern":"(?<year>\\d{4})"}},"title":{"sources":[{"selector":".p-schedule__item-title-top"},{"selector":".p-schedule__item-title"},{"selector":".p-schedule__item-title-bottom"}],"mode":"join"},"artists":{"selector":".p-schedule__item-lineup","split":"\\s*[/／]\\s*","strip":["\\s*※順不同$"]},"times":{"source":{"selector":".p-schedule__item-open"},"patterns":["OPEN\\s*(?<open>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"},"status":[{"value":"cancelled","when":{"text_matches":"【公演中止】"}}]}}' , needs_review = 0 WHERE id = 'src_venue-daikanyama-unit';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"The Events Calendar（WordPress プラグイン）の月表示 https://batica.jp/events/（既定で当月。前後月の週の端の日も入る）。中目黒 solfa と同じプラグイン・同じ設定。1 公演 = article.tribe-events-calendar-month__calendar-event（モバイル用の複製 mobile-event と、終日の multiday-event は数えない）。日付はツールチップの time[datetime]（YYYY-MM-DD）。最初の time[datetime] は開始時刻（HH:MM）で、説明文では OPEN と書かれているので open に写す（終了時刻は捨てる）。「TBA」の仮枠は skip。一覧に出演者・完売表記はない。","item":"article.tribe-events-calendar-month__calendar-event","skip":[{"reason":"placeholder: TBA","when":{"in":".tribe-events-calendar-month__calendar-event-title","text_matches":"^TBA$"}}],"fields":{"date":{"source":{"selector":".tribe-events-calendar-month__calendar-event-tooltip-datetime time","attr":"datetime"},"pattern":"^(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})$"},"title":{"sources":[{"selector":".tribe-events-calendar-month__calendar-event-title"}],"mode":"first"},"times":{"source":{"selector":".tribe-events-calendar-month__calendar-event-datetime time","attr":"datetime"},"patterns":["^(?<open>\\d{1,2}:\\d{2})$"]},"detail_url":{"selector":".tribe-events-calendar-month__calendar-event-title a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-ebisu-batica';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"The Events Calendar（WordPress プラグイン）の月表示 https://nakameguro-solfa.com/events/（既定で当月。前後月の週の端の日も入る）。恵比寿 BATICA と同じプラグイン・同じ設定。休業日の「CLOSED」は終日の multiday-event として出るので item に入らない。1 公演 = article.tribe-events-calendar-month__calendar-event（モバイル用の複製 mobile-event と、終日の multiday-event は数えない）。日付はツールチップの time[datetime]（YYYY-MM-DD）。最初の time[datetime] は開始時刻（HH:MM）で、説明文の OPEN と一致するので open に写す（終了時刻は捨てる）。「TBA」の仮枠は skip。一覧に出演者・完売表記はない。","item":"article.tribe-events-calendar-month__calendar-event","skip":[{"reason":"placeholder: TBA","when":{"in":".tribe-events-calendar-month__calendar-event-title","text_matches":"^TBA$"}}],"fields":{"date":{"source":{"selector":".tribe-events-calendar-month__calendar-event-tooltip-datetime time","attr":"datetime"},"pattern":"^(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})$"},"title":{"sources":[{"selector":".tribe-events-calendar-month__calendar-event-title"}],"mode":"first"},"times":{"source":{"selector":".tribe-events-calendar-month__calendar-event-datetime time","attr":"datetime"},"patterns":["^(?<open>\\d{1,2}:\\d{2})$"]},"detail_url":{"selector":".tribe-events-calendar-month__calendar-event-title a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-nakameguro-solfa';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"WP Event Manager の一覧（https://circus-tokyo.jp/schedule/）。月別 URL はなく、直近の公演（約 24 件）が SSR で出る。それより先は Ajax の「もっと見る」なので取れない。日付と時刻は .wpem-event-date-time-text の「2026-11-27 - 23:00 - 2026-11-28 - 05:00」から取り、先頭の時刻を start、終了は捨てる（WOMB と同じく開始-終了の表記で open は別記されない）。日付は興行日（開始日）。一覧に出演者はない。完売はタイトル先頭の【SOLD OUT】だけなので、それを sold_out に写す（タイトルからは外さない）。","item":".wpem-event-layout-wrapper","fields":{"date":{"source":{"selector":".wpem-event-date-time-text"},"pattern":"^(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})"},"title":{"sources":[{"selector":".wpem-event-title .wpem-heading-text"}],"mode":"first"},"times":{"source":{"selector":".wpem-event-date-time-text"},"patterns":["^\\d{4}-\\d{2}-\\d{2}\\s*-\\s*(?<start>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"},"status":[{"value":"sold_out","when":{"in":".wpem-event-title","text_matches":"【SOLD OUT】"}}]}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-circus';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"月別の静的ページ。日付は section の直前にある <a name=\"YYMMDD\"> から取る。出演者欄（.artist）は公演名のことも多く、タイトルは .details-title が空なら .artist で補う。時刻は dt が OPEN/START の次の dd から取り、「15:00 / 16:00」は open/start、24:00 のような単独値は start のみ（open なし）。1 日 2 部の「①13:45 / 14:30 ②18:15 / 19:00」は先頭の部だけを取る（2 部目は未対応）。完売表記はページに無く、延期告知はあっても status は割り当てない。","url_template":"https://www.duomusicexchange.com/schedule/{YYYY}/index_{YYYY}-{MM}.html","item":"section#daybox","fields":{"date":{"source":{"from":"prev-sibling","attr":"name"},"pattern":"^(?<yy>\\d{2})(?<month>\\d{2})(?<day>\\d{2})$"},"title":{"sources":[{"selector":".details-title"},{"selector":".artist"}],"mode":"first"},"artists":{"selector":".artist","split":"\\s*[/／\\n]\\s*","strip":["【[^】]*】"]},"times":{"source":{"label":{"selector":"dt","pattern":"^OPEN/START$"}},"patterns":["(?<open>\\d{1,2}:\\d{2})\\s*/\\s*(?<start>\\d{1,2}:\\d{2})","^(?<start>\\d{1,2}:\\d{2})$"]},"price_text":{"label":{"selector":"dt","pattern":"^ADV\\./DOOR$"}},"ticket_url":{"label":{"selector":"dt","pattern":"^Ticket\\.$"},"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-duo';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"月別ページ ?month=YYYY-MM（WordPress）。1 公演 = a.pickup_btn.schedule で、ページ内は「今後の公演 → NEXT MONTH PICK UP（翌月の一部）→ FINISHED（当月の終了分）」の順に並ぶので DOM 順は日付順ではない。日付は data-schedule（YYYY-MM-DD）。一覧に開場・開演の時刻はなく、DAY / NIGHT の区分（.time_zone）だけなので時刻は null。同じ日の DAY と NIGHT は別公演。出演者は .member を / で分け、「MC：」「ゲスト：」「(O.A.)」の前置きと末尾の「他」「ほか」を外し、「※」で始まる注記と and more… は捨てる。","url_template":"https://www.lamama.net/schedule/?month={YYYY}-{MM}","item":"a.pickup_btn.schedule","fields":{"date":{"source":{"attr":"data-schedule"},"pattern":"^(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})$"},"title":{"sources":[{"selector":".event"}],"mode":"first"},"artists":{"selector":".member","split":"\\s*[/／]\\s*","strip":["^\\s*MC[：:]\\s*","^\\s*ゲスト[：:]\\s*","^\\s*\\(O\\.A\\.\\)\\s*","\\s*(他|ほか)\\s*$"],"exclude":["^※","^(and more…?|…|\\.{2,})$"]},"detail_url":{"attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-lamama';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"shibuya-o.com 共通テーマ（O-nest / O-Crest / O-WEST で同じ構造）。月別ページ ?y=YYYY&m=M。日付は 11 / 01 形式で年は URL の y から取る（無ければ now から推定）。タイトルは title-top / title-main / title-bottom を連結。.p-scheduled-card__soldout（SOLD OUT）は sold_out に写す。同じ日の 1 部・2 部は別カード。","url_template":"https://shibuya-o.com/crest/schedule/?y={YYYY}&m={M}","item":".p-schedule__list > .p-scheduled-card","fields":{"date":{"source":{"selector":".p-scheduled-card__date-item"},"pattern":"(?<month>\\d{1,2})\\s*/\\s*(?<day>\\d{1,2})","year_source":{"source":{"from":"url"},"pattern":"[?&]y=(?<year>\\d{4})"}},"title":{"sources":[{"selector":".p-scheduled-card__title-top"},{"selector":".p-scheduled-card__title-main"},{"selector":".p-scheduled-card__title-bottom"}],"mode":"join"},"artists":{"selector":".p-scheduled-card__artist-item"},"times":{"source":{"selector":".p-scheduled-card__date-open"},"patterns":["OPEN\\s*(?<open>\\d{1,2}:\\d{2})\\s*/\\s*START\\s*(?<start>\\d{1,2}:\\d{2})","START\\s*(?<start>\\d{1,2}:\\d{2})","OPEN\\s*(?<open>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"},"status":[{"value":"sold_out","when":{"has":".p-scheduled-card__soldout"}}]}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-o-crest';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"shibuya-o.com 共通テーマ（O-nest / O-Crest / O-WEST で同じ構造）。月別ページ ?y=YYYY&m=M。日付は 11 / 01 形式で年は URL の y から取る（無ければ now から推定）。タイトルは title-top / title-main / title-bottom を連結。.p-scheduled-card__soldout（SOLD OUT）は sold_out に写す。同じ日の 1 部・2 部は別カード。","url_template":"https://shibuya-o.com/nest/schedule/?y={YYYY}&m={M}","item":".p-schedule__list > .p-scheduled-card","fields":{"date":{"source":{"selector":".p-scheduled-card__date-item"},"pattern":"(?<month>\\d{1,2})\\s*/\\s*(?<day>\\d{1,2})","year_source":{"source":{"from":"url"},"pattern":"[?&]y=(?<year>\\d{4})"}},"title":{"sources":[{"selector":".p-scheduled-card__title-top"},{"selector":".p-scheduled-card__title-main"},{"selector":".p-scheduled-card__title-bottom"}],"mode":"join"},"artists":{"selector":".p-scheduled-card__artist-item"},"times":{"source":{"selector":".p-scheduled-card__date-open"},"patterns":["OPEN\\s*(?<open>\\d{1,2}:\\d{2})\\s*/\\s*START\\s*(?<start>\\d{1,2}:\\d{2})","START\\s*(?<start>\\d{1,2}:\\d{2})","OPEN\\s*(?<open>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"},"status":[{"value":"sold_out","when":{"has":".p-scheduled-card__soldout"}}]}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-o-nest';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"shibuya-o.com 共通テーマ（O-nest / O-Crest / O-WEST で同じ構造）。月別ページ ?y=YYYY&m=M。日付は 11 / 01 形式で年は URL の y から取る（無ければ now から推定）。タイトルは title-top / title-main / title-bottom を連結。.p-scheduled-card__soldout（SOLD OUT）は sold_out に写す。同じ日の 1 部・2 部は別カード。","url_template":"https://shibuya-o.com/west/schedule/?y={YYYY}&m={M}","item":".p-schedule__list > .p-scheduled-card","fields":{"date":{"source":{"selector":".p-scheduled-card__date-item"},"pattern":"(?<month>\\d{1,2})\\s*/\\s*(?<day>\\d{1,2})","year_source":{"source":{"from":"url"},"pattern":"[?&]y=(?<year>\\d{4})"}},"title":{"sources":[{"selector":".p-scheduled-card__title-top"},{"selector":".p-scheduled-card__title-main"},{"selector":".p-scheduled-card__title-bottom"}],"mode":"join"},"artists":{"selector":".p-scheduled-card__artist-item"},"times":{"source":{"selector":".p-scheduled-card__date-open"},"patterns":["OPEN\\s*(?<open>\\d{1,2}:\\d{2})\\s*/\\s*START\\s*(?<start>\\d{1,2}:\\d{2})","START\\s*(?<start>\\d{1,2}:\\d{2})","OPEN\\s*(?<open>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"},"status":[{"value":"sold_out","when":{"has":".p-scheduled-card__soldout"}}]}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-o-west';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"CLUB QUATTRO 共通テーマ（渋谷・名古屋・梅田・広島で同じ構造）。月別ページ ?ym=YYYYMM。日付は li の data-event-date（YYYY-MM-DD）から取る。txt-01 が出演者（/ と <br> 区切り。[ ] 内のメンバー表記も / で分かれてしまうのは未対応）、txt-02 が公演名で、公演名が空なら出演者で補う。時刻は dt が 開場/開演 の次の dd。「1回目 15:30 / 16:00. 2回目 …」は先頭の回だけ。完売表記は一覧にないので status は割り当てない。","url_template":"https://www.club-quattro.com/shibuya/schedule/?ym={YYYY}{MM}","item":".cmn-event-list > li.list-item","fields":{"date":{"source":{"attr":"data-event-date"},"pattern":"^(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})$"},"title":{"sources":[{"selector":".txt-02"},{"selector":".txt-01"}],"mode":"first"},"artists":{"selector":".txt-01","split":"\\s*[/／\\n]\\s*","strip":["\\s*[（(]※?順不同[)）]$","【[^】]*】"]},"times":{"source":{"label":{"selector":"dt","pattern":"^開場/開演$"}},"patterns":["(?<open>\\d{1,2}:\\d{2})\\s*/\\s*(?<start>\\d{1,2}:\\d{2})"]},"price_text":{"label":{"selector":"dt","pattern":"^料金$"}},"detail_url":{"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-quattro';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"月別ページ ?ym=YYYY-MM（WordPress・Elementor のショートコード）。日付は .date の「2026-11-03 TUE」。一覧に時刻はない。出演者欄 .dj は <br> 区切りで、[DJ] [GUEST DJ] [LIVE] のような見出し行が混ざるので、行頭の見出しを外す（見出しだけの行は空になって捨てられる）。バンドの編成行（(Gt)名前 など）も 1 行 1 組として入る（区別できない）。同じ日の LIVE と DJ の 2 公演は別カード。","url_template":"https://theroom.jp/schedule/?ym={YYYY}-{MM}","item":".schedule-card","fields":{"date":{"source":{"selector":".date"},"pattern":"^(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})"},"title":{"sources":[{"selector":".title"}],"mode":"first"},"artists":{"selector":".dj","split":"\\s*\\n\\s*","strip":["^\\[[^\\]]*\\]\\s*"]},"detail_url":{"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-theroom';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"トップページ（https://www.womb.co.jp/ja）の SSR カードを使う。一覧本体は RSC の JSON にあるが 2.8MB と重く、DOM ルールの範囲外。このため取れるのは直近の約 10 件のみ（フィクスチャでは 10 件）で、月単位の網羅はできない。日付は年なし（11/21 SAT）なので now から推定する。時刻 `23:00-4:30` は先頭を start とし終了は捨てる（WOMB の表記は開始-終了で open は別記されない）。url_template は使わず sources の URL をトップページに向ける必要がある。","item":".events-grid > article.event-card","fields":{"date":{"source":{"selector":".event-date"},"pattern":"(?<month>\\d{1,2})/(?<day>\\d{1,2})"},"title":{"sources":[{"selector":".event-title"}],"mode":"first"},"artists":{"selector":".event-artists","split":"\\s*,\\s*"},"times":{"source":{"selector":".event-time"},"patterns":["^(?<start>\\d{1,2}:\\d{2})\\s*-"]},"detail_url":{"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shibuya-womb';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"LOFT PROJECT 共通テーマ。日付は time 内の year/month/day を空白区切りで拾う。.soldout は「予約は締めきりました」で完売とは限らないので status には写さない（null のまま）。open が空のカードは時刻 null。出演者末尾の <li>...</li> は省略記号なので除外。","url_template":"https://www.loft-prj.co.jp/schedule/shelter/schedule?scheduleyear={YYYY}&schedulemonth={M}","item":".block_schedule_list .list > .column","fields":{"date":{"source":{"selector":"time"},"pattern":"(?<year>\\d{4})\\s+(?<month>\\d{1,2})\\s+(?<day>\\d{1,2})"},"title":{"sources":[{"selector":".c_title span"}],"mode":"first"},"artists":{"selector":".artist_tag li","exclude":["^(\\.{2,}|…|and more…?)$"]},"times":{"source":{"selector":".open"},"patterns":["OPEN\\s*(?<open>\\d{1,2}:\\d{2})\\s*-\\s*START\\s*(?<start>\\d{1,2}:\\d{2})","START\\s*(?<start>\\d{1,2}:\\d{2})","OPEN\\s*(?<open>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shimokitazawa-shelter';
UPDATE sources SET config_json = '{"version":1,"strategy":"dom","comment":"LOFT PROJECT 共通テーマ（SHELTER と同じ構造）。メンテナンス等の非公演カードは skip で落とす。24:00 のような深夜開演はそのまま受け入れる。出演者末尾の <li>...</li> と <li>and more…</li> は省略記号なので除外。","url_template":"https://www.loft-prj.co.jp/schedule/loft/schedule?scheduleyear={YYYY}&schedulemonth={M}","item":".block_schedule_list .list > .column","skip":[{"reason":"non-event: maintenance","when":{"in":".c_title","text_matches":"^メンテナンス$"}}],"fields":{"date":{"source":{"selector":"time"},"pattern":"(?<year>\\d{4})\\s+(?<month>\\d{1,2})\\s+(?<day>\\d{1,2})"},"title":{"sources":[{"selector":".c_title span"}],"mode":"first"},"artists":{"selector":".artist_tag li","exclude":["^(\\.{2,}|…|and more…?)$"]},"times":{"source":{"selector":".open"},"patterns":["OPEN\\s*(?<open>\\d{1,2}:\\d{2})\\s*-\\s*START\\s*(?<start>\\d{1,2}:\\d{2})","START\\s*(?<start>\\d{1,2}:\\d{2})","OPEN\\s*(?<open>\\d{1,2}:\\d{2})"]},"detail_url":{"selector":"a","attr":"href"}}}' , needs_review = 0 WHERE id = 'src_venue-shinjuku-loft';
